```cs
private static Win32Exception CreateDetailedException(string prefix, int errorCode, string fileName, string? workingDirectory)
{
    string directoryForException = string.IsNullOrEmpty(workingDirectory) ? Directory.GetCurrentDirectory() : workingDirectory;
    string msg = SR.Format(SR.FailedToStartFileDirectory, fileName, directoryForException, prefix);
    return new Win32Exception(errorCode, msg);
}
